//+------------------------------------------------------------------+
int
CStateStore::GetDoubleArray(
const
string
key,
double
&arr[])
  {
int
i = Find(key);
if
(i <
0
|| m_vals[i] ==
""
)
     {
ArrayResize
(arr,
0
);
return
(
0
);
     }
string
parts[];
int
n =
StringSplit
(m_vals[i], ' ', parts);
ArrayResize
(arr, n);
for
(
int
k =
0
; k < n; k++)
      arr[k] =
StringToDouble
(parts[k]);
